package com.andye.warmod.antiair;import net.minecraft.world.phys.Vec3;public final class AntiAirTrajectory{private AntiAirTrajectory(){}public static Vec3 boostPosition(AntiAirFlightPlan p,double elapsed){double u=Math.max(0,Math.min(1,(elapsed-p.ignitionTicks())/p.boostTicks()));return p.launchPosition().lerp(p.burnoutPosition(),u*u*(3-2*u));}public static Vec3 boostVelocity(AntiAirFlightPlan p,double elapsed){return boostPosition(p,elapsed+.25).subtract(boostPosition(p,elapsed-.25)).scale(2);}}